12: // Opt specifies optional arguments for customizing queries and driver
13: // construction.
14: type Opt func(*Options)
15: 
16: // Tracing enables Rego tracing for a single query.
17: // If tracing is enabled for the Driver, Tracing(false) does not disable Tracing.
18: func Tracing(enabled bool) Opt {
19: 	return func(cfg *Options) {
20: 		if cfg.EngineCfg == nil {
21: 			cfg.EngineCfg = &EngineCfg{}
22: 		}
23: 		cfg.EngineCfg.TracingEnabled = enabled
24: 	}
25: }
