28: 	StatsEnabled bool
29: }
30: 
31: // Stats(true) enables the driver to gather evaluation stats for a single
32: // query. If stats is enabled for the Driver at construction time, then
33: // Stats(false) does not disable Stats for this single query.
34: func Stats(enabled bool) Opt {
35: 	return func(cfg *Options) {
36: 		if cfg.DriverCfg == nil {
37: 			cfg.DriverCfg = &DriverCfg{}
38: 		}
39: 		cfg.DriverCfg.StatsEnabled = enabled
40: 	}
